diff --git a/src/main/resources/db/migration/V2__add_guest_identification_types.sql b/src/main/resources/db/migration/V2__add_guest_identification_types.sql
new file mode 100644
index 0000000..8bf5a9c
--- /dev/null
+++ b/src/main/resources/db/migration/V2__add_guest_identification_types.sql
@@ -0,0 +1,12 @@
+-- Adiciona suporte para empresa (CNPJ) e estrangeiros (passaporte)
+ALTER TABLE reservations
+    ALTER COLUMN guest_cpf DROP NOT NULL,
+    ADD COLUMN company_cnpj text,
+    ADD COLUMN company_name text,
+    ADD COLUMN guest_passport text,
+    ADD COLUMN guest_country text,
+    ADD CONSTRAINT one_identification_type CHECK (
+        (guest_cpf IS NOT NULL AND company_cnpj IS NULL AND guest_passport IS NULL) OR
+        (guest_cpf IS NULL AND company_cnpj IS NOT NULL AND company_name IS NOT NULL AND guest_passport IS NULL) OR
+        (guest_cpf IS NULL AND company_cnpj IS NULL AND guest_passport IS NOT NULL AND guest_country IS NOT NULL)
+    );
diff --git a/src/test/java/hotel/web/HttpApiTest.java b/src/test/java/hotel/web/HttpApiTest.java
index f9a3f6f..8b2c292 100644
--- a/src/test/java/hotel/web/HttpApiTest.java
+++ b/src/test/java/hotel/web/HttpApiTest.java
@@ -119,4 +119,115 @@ class HttpApiTest {
         assertEquals(400, get("/reports/revenue?month=july").statusCode());
         assertEquals(400, get("/reports/occupancy").statusCode());
     }
+
+    @Test
+    void acceptsCompanyReservationsWithCnpjAndGeneratesInvoice() throws Exception {
+        String companyReservation = """
+                {"roomNumber": 201, "guestName": "Ana Souza", "guestEmail": "ana@example.com",
+                 "companyCnpj": "12.345.678/0001-90", "companyName": "Tecnosul Ltda",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> created = post("/reservations", companyReservation);
+        assertEquals(201, created.statusCode());
+        JsonNode reservation = json.readTree(created.body());
+        long id = reservation.get("id").asLong();
+        assertEquals("12.345.678/0001-90", reservation.get("companyCnpj").asText());
+        assertEquals("Tecnosul Ltda", reservation.get("companyName").asText());
+        assertTrue(reservation.get("guestCpf").isNull());
+
+        post("/reservations/" + id + "/confirmation", "");
+
+        JsonNode messages = json.readTree(get("/messages").body());
+        assertEquals(1, messages.size());
+        JsonNode message = messages.get(0);
+        assertEquals("ana@example.com", message.get("to").asText());
+        String emailBody = message.get("body").asText();
+        assertTrue(emailBody.contains("Olá, Ana Souza!"));
+        assertTrue(emailBody.contains("Sua reserva na Pousada Maré Alta está confirmada"));
+        assertTrue(emailBody.contains("Fatura de hospedagem"));
+
+        HttpResponse<String> document = get("/reservations/" + id + "/document");
+        JsonNode receipt = json.readTree(document.body());
+        assertEquals("Fatura de hospedagem", receipt.get("title").asText());
+        String text = receipt.get("text").asText();
+        assertTrue(text.contains("Empresa: Tecnosul Ltda"));
+        assertTrue(text.contains("CNPJ 12.345.678/0001-90"));
+        assertTrue(text.contains("Hóspede: Ana Souza"));
+        assertTrue(text.contains("ISS retido (5%): R$ 38,99"));
+    }
+
+    @Test
+    void acceptsForeignGuestsWithPassportAndGeneratesEnglishReceipt() throws Exception {
+        String foreignReservation = """
+                {"roomNumber": 201, "guestName": "John Smith", "guestEmail": "john@example.com",
+                 "guestPassport": "X1234567", "guestCountry": "United Kingdom",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> created = post("/reservations", foreignReservation);
+        assertEquals(201, created.statusCode());
+        JsonNode reservation = json.readTree(created.body());
+        long id = reservation.get("id").asLong();
+        assertEquals("X1234567", reservation.get("guestPassport").asText());
+        assertEquals("United Kingdom", reservation.get("guestCountry").asText());
+        assertTrue(reservation.get("guestCpf").isNull());
+
+        post("/reservations/" + id + "/confirmation", "");
+
+        JsonNode messages = json.readTree(get("/messages").body());
+        assertEquals(1, messages.size());
+        JsonNode message = messages.get(0);
+        assertEquals("john@example.com", message.get("to").asText());
+        String emailBody = message.get("body").asText();
+        assertTrue(emailBody.contains("Olá, John Smith!"));
+        assertTrue(emailBody.contains("Sua reserva na Pousada Maré Alta está confirmada"));
+        assertTrue(emailBody.contains("Booking receipt"));
+
+        HttpResponse<String> document = get("/reservations/" + id + "/document");
+        JsonNode receipt = json.readTree(document.body());
+        assertEquals("Booking receipt", receipt.get("title").asText());
+        String text = receipt.get("text").asText();
+        assertTrue(text.contains("Guest: John Smith"));
+        assertTrue(text.contains("passport X1234567"));
+        assertTrue(text.contains("United Kingdom"));
+        assertTrue(text.contains("Check-in: 2027-03-10"));
+        assertTrue(text.contains("Check-out: 2027-03-12"));
+        assertTrue(text.contains("2 nights"));
+        assertTrue(text.contains("BRL 779.80"));
+    }
+
+    @Test
+    void rejectsReservationsWithoutExactlyOneIdentificationType() throws Exception {
+        String noIdentification = """
+                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> response = post("/reservations", noIdentification);
+        assertEquals(400, response.statusCode());
+        assertTrue(json.readTree(response.body()).get("message").asText().contains("exactly one identification"));
+
+        String twoIdentifications = """
+                {"roomNumber": 201, "guestName": "Test", "guestEmail": "test@example.com",
+                 "guestCpf": "111.222.333-44", "companyCnpj": "12.345.678/0001-90", "companyName": "Test Ltda",
+                 "checkIn": "2027-03-10", "checkOut": "2027-03-12", "guests": 2, "ratePlan": "STANDARD"}
+                """;
+        response = post("/reservations", twoIdentifications);
+        assertEquals(400, response.statusCode());
+        assertTrue(json.readTree(response.body()).get("message").asText().contains("exactly one identification"));
+
