  8	/** How money and dates are written in the texts the guest reads. */
  9	public final class TextFormat {
 10	
 11	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
 12	    private static final Locale US = Locale.US;
 13	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 14	    private static final DateTimeFormatter ISO_DATE = DateTimeFormatter.ISO_LOCAL_DATE;
 15	
 16	    private TextFormat() {
 17	    }
 18	
 19	    public static String money(BigDecimal amount) {
 20	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
 21	    }
 22	
 23	    public static String moneyEnglish(BigDecimal amount) {
 24	        return "BRL " + String.format(US, "%,.2f", amount);
 25	    }
 26	
 27	    public static String date(LocalDate date) {
 28	        return BRAZILIAN_DATE.format(date);
 29	    }
 30	
 31	    public static String dateEnglish(LocalDate date) {
 32	        return ISO_DATE.format(date);
 33	    }
 34	}

