109	    private static NewReservation readNewReservation(Context ctx) {
110	        CreateReservationRequest body;
111	        try {
112	            body = ctx.bodyAsClass(CreateReservationRequest.class);
113	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
114	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
115	        }
116	        if (body == null
117	                || body.roomNumber() == null
118	                || isBlank(body.guestName())
119	                || isBlank(body.guestEmail())
120	                || body.checkIn() == null
121	                || body.checkOut() == null
122	                || body.guests() == null
123	                || body.ratePlan() == null) {
124	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
125	        }
126	
127	        boolean hasCpf = !isBlank(body.guestCpf());
128	        boolean hasCompany = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
129	        boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());
130	
131	        int identificationCount = (hasCpf ? 1 : 0) + (hasCompany ? 1 : 0) + (hasPassport ? 1 : 0);
132	        if (identificationCount != 1) {
133	            throw new HotelException(ErrorCode.INVALID_REQUEST,
134	                    "exactly one identification type is required: guestCpf, or (companyCnpj and companyName), "
135	                            + "or (guestPassport and guestCountry)");
136	        }
137	
138	        Guest guest = new Guest(
139	                body.guestName(),
140	                body.guestEmail(),
141	                hasCpf ? body.guestCpf() : null,
142	                hasCompany ? body.companyCnpj() : null,
143	                hasCompany ? body.companyName() : null,
144	                hasPassport ? body.guestPassport() : null,
145	                hasPassport ? body.guestCountry() : null);
146	        return new NewReservation(
147	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
148	    }
